update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance industrielle à Limoges et en Haute-Vienne","mecanisme":"Un four de porcelaine qui dérive de quelques degrés. Un métier de découpe du cuir arrêté à Saint-Junien. Une ligne de carton qui tourne sans interruption vers Brive. Le Limousin fait travailler des machines anciennes à des exigences modernes. Nos techniciens itinérants couvrent la Haute-Vienne, la Corrèze et la Creuse, et se déplacent partout en France.","cta":"Demander une intervention à Limoges","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 couvre les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 100","libelle":"collaborateurs, mécaniciens, électriciens, automaticiens, roboticiens"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental"},{"valeur":"+ 80","libelle":"clients réguliers, sur plus de 120 clients accompagnés"}]},{"type":"probleme","punchline":"Une presse d''émaillage tombe le lundi matin. Le fournisseur de la machine a fermé il y a quinze ans, et la pièce n''existe plus au catalogue.","puces":[{"accroche":"Le parc vieillit plus vite que les compétences ne se renouvellent.","texte":"Ateliers cuir, papier, céramique : beaucoup d''équipements uniques, peu de gens qui savent encore les lire."},{"accroche":"Le recrutement local tourne à vide.","texte":"Les annonces de technicien de maintenance s''empilent, les candidatures manquent, et l''attente se paie en arrêts."},{"accroche":"La cuisson n''attend pas le devis.","texte":"En céramique, une dérive thermique gâche une fournée entière avant que quiconque ait eu le temps de réagir."},{"accroche":"Le continu ne laisse pas de fenêtre.","texte":"Papier et carton tournent douze mois sur douze : le préventif se planifie des mois à l''avance ou il ne se fait jamais."},{"accroche":"Un site isolé finit par être négligé.","texte":"Sur la Creuse et le plateau, le prestataire vient quand il passe. Vos équipements ne suivent pas ce calendrier."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Dépannage et remise en état","texte":"sur site, du moteur au circuit hydraulique, avec recherche de cause racine."},"benefice":"La panne ne revient pas le mois suivant sous un autre nom."},{"prestation":{"accroche":"Rétrofit plutôt que remplacement","texte":"sur les machines anciennes : automate, variation de vitesse, supervision."},"benefice":"Vous prolongez un outil amorti au lieu d''investir dans un équipement neuf."},{"prestation":{"accroche":"Préventif planifié","texte":"calé sur vos arrêts programmés et vos creux de saison."},"benefice":"Les révisions se font quand la production le permet, pas quand la casse l''impose."},{"prestation":{"accroche":"Maîtrise thermique et fluides","texte":"fours, échangeurs, réseaux d''air comprimé, chasse aux fuites."},"benefice":"Les dérives énergétiques se voient sur vos relevés avant de se voir sur la facture."},{"prestation":{"accroche":"Domaines combinés","texte":"[mécanique](/expertises/mecanique/), [électrique](/expertises/electrique/), [automatisme](/expertises/automatisme/), [soudure](/expertises/soudure/)."},"benefice":"Un seul interlocuteur quand le défaut traverse trois spécialités."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", pour les sites en service continu."},"benefice":"La ligne de carton du dimanche soir trouve quelqu''un au bout du fil."},{"prestation":{"accroche":"Technicien intégré à votre équipe","texte":"avec l''offre [Résidence](/offres/residence/), prise de poste en 2 à 3 semaines."},"benefice":"Le poste que vous n''arrivez pas à pourvoir est tenu, remplacement assuré."},{"prestation":{"accroche":"Contrat [Zéro arrêt](/offres/zero-arret/)","texte":"visites planifiées, priorité en cas de panne, astreinte en option."},"benefice":"Le préventif cesse d''être la première victime du carnet de commandes."}]},{"type":"deroule","etapes":[{"titre":"Premier échange","texte":"vous décrivez la situation et les machines concernées. Des photos accélèrent le diagnostic. Rappel dans l''heure aux horaires ouvrés."},{"titre":"Qualification","texte":"accès au site, habilitations, environnement, pièces disponibles. Le champ d''intervention s''écrit noir sur blanc."},{"titre":"Devis ferme","texte":"périmètre, créneaux, conditions. Rien ne se découvre en fin de mission."},{"titre":"Intervention","texte":"accueil sécurité, consignation si nécessaire, diagnostic, réparation, sécurisation du redémarrage."},{"titre":"Compte rendu","texte":"opérations, temps passé, pièces à prévoir, préconisations, versés dans votre GMAO."},{"titre":"Passage suivant","texte":"chaque visite capitalise sur l''état des lieux du premier passage. L''historique machine se construit."}]},{"type":"garanties","puces":[{"accroche":"Un profil vérifié avant l''arrivée sur site.","texte":"Entretien technique et comportemental, 10 % des candidats retenus, résultats d''évaluation présentés. Vos machines ne servent pas de terrain d''apprentissage."},{"accroche":"Une réponse franche sur la faisabilité.","texte":"Si un site isolé ou une machine hors de notre champ ne peut pas être tenu correctement, le chargé d''affaires le dit au premier échange."},{"accroche":"Des données qui restent les vôtres.","texte":"Comptes rendus versés dans votre outil, historique à jour, confidentialité respectée. Vous ne dépendez pas de nos fichiers."}]},{"type":"cta","question":"Besoin de fiabiliser une machine que plus personne ne sait dépanner ?","bouton":"Demander une intervention à Limoges","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Un technicien polyvalent intégré sur un site papier et emballage","texte":", parc machines hétérogène en forte cadence, 2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"},{"titre":"Un automaticien SIEMENS affecté au démarrage d''une nouvelle ligne de production","texte":", sur les trimestres de montée en charge","lienLibelle":"Étude de cas MERSEN : nouvelles lignes","lienHref":"/preuves/mersen/"},{"titre":"Le pilotage d''un service maintenance confié à un responsable Migen intégré sur site","texte":", pendant une transition d''équipe","lienLibelle":"Étude de cas ERIKS","lienHref":"/preuves/eriks/"},{"titre":"Un technicien en renfort pendant les congés d''été","texte":", pour garder les équipements opérationnels en juillet et août","lienLibelle":"Étude de cas OGF : arrêt estival","lienHref":"/preuves/ogf-arret-estival/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment à Limoges, alors que votre siège est à Lyon ?","reponse":"Oui. Nous n''avons pas d''agence en Haute-Vienne et nous le disons : nos techniciens se déplacent partout en France et interviennent sur site. Votre demande est rappelée dans l''heure aux horaires ouvrés, et vous savez dès le premier appel si nous pouvons tenir votre besoin."},{"question":"Couvrez-vous Brive-la-Gaillarde, Saint-Junien et Guéret ?","reponse":"Oui. Limoges et Couzeix, Saint-Junien et Aixe-sur-Vienne à l''ouest, Brive-la-Gaillarde en Corrèze, Guéret et la Creuse. Les sites isolés entrent dans les tournées, pas dans une liste d''attente."},{"question":"Nos machines sont anciennes et non documentées. Vous savez faire ?","reponse":"C''est le quotidien du bassin. Le premier passage sert d''état des lieux. Le rétrofit se décide machine par machine, sur l''usage réel et le coût de remplacement, jamais par principe."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"L''offre Zéro arrêt fonctionne en abonnement, trois niveaux de couverture, sur devis, engagement type 6 mois renouvelable. Le diagnostic de départ est gratuit et le périmètre s''écrit équipement par équipement."},{"question":"Que se passe-t-il en cas de panne un dimanche soir ?","reponse":"L''astreinte 24/24 et 7/7 prend l''appel et mobilise un technicien. Le circuit d''appel et l''ordre des priorités sont écrits au devis, site par site, avant la première urgence."},{"question":"Pouvez-vous détacher un technicien dans notre usine ?","reponse":"Oui, en résidence : technicien intégré à votre équipe, encadré par un référent technique Migen, opérationnel en 2 à 3 semaines. Absence ou départ, un profil équivalent arrive briefé sur vos machines."}]},{"type":"ctaFinal","question":"Besoin d''un technicien capable de tenir un parc que personne ne veut reprendre ?","bouton":"Demander une intervention à Limoges","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/maintenance-industrielle-limoges/';
